<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import{api,type Model,type Status,type Trajectory,type Video}from'./api';
const video=ref<Video|null>(null),media=ref<HTMLVideoElement|null>(null),trajectory=ref<Trajectory|null>(null),status=ref<Status>({state:'idle',runId:null,videoId:null,stage:'Готово'}),saved=ref<any[]>([]),error=ref(''),playing=ref(false),time=ref(0),speed=ref(1),view=ref<'map'|'space'>('map'),modelId=ref('');const settings=ref({sampleHz:5,maxImageSize:640,maxFeatures:1500,threads:2,overlap:5});
const model=computed<Model|undefined>(()=>trajectory.value?.models.find(m=>m.id===modelId.value)||trajectory.value?.models[0]),samples=computed(()=>model.value?.samples||[]),estimated=computed(()=>samples.value.filter(s=>s.status==='estimated'&&s.position)),points=computed(()=>{const p=estimated.value;if(!p.length)return[];const xs=p.map(s=>s.position![0]),zs=p.map(s=>s.position![2]),minx=Math.min(...xs),minz=Math.min(...zs),ax=Math.max(...xs)-minx||1,az=Math.max(...zs)-minz||1;return p.map(s=>({x:35+(s.position![0]-minx)/ax*485,y:260-(s.position![2]-minz)/az*210,t:s.timeSec}))}),path=computed(()=>points.value.map((p,i)=>(i?'L':'M')+` ${p.x} ${p.y}`).join(' ')),active=computed(()=>points.value.reduce((a,p)=>Math.abs(p.t-time.value)<Math.abs(a.t-time.value)?p:a,points.value[0]));
async function refresh(){try{status.value=await api.status();if(status.value.state==='running')setTimeout(refresh,900);else if(status.value.runId&&['succeeded','partial'].includes(status.value.state)){await load(status.value.runId);loadSaved()}}catch(e){error.value=(e as Error).message}}async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f)try{video.value=await api.upload(f)}catch(e){error.value=(e as Error).message}}async function start(){if(video.value)try{status.value=await api.start(video.value.id,settings.value);refresh()}catch(e){error.value=(e as Error).message}}async function load(id:string){try{trajectory.value=await api.result(id);video.value=trajectory.value.video;modelId.value=trajectory.value.primaryModelId}catch(e){error.value=(e as Error).message}}async function loadSaved(){try{saved.value=await api.results()}catch{saved.value=[]}}function sync(e:Event){time.value=(e.target as HTMLVideoElement).currentTime}function seek(){if(media.value)media.value.currentTime=time.value}function toggle(){if(!media.value)return;playing.value?media.value.pause():media.value.play().catch(()=>{});playing.value=!playing.value}function rate(){if(media.value)media.value.playbackRate=speed.value}function exportData(f:'json'|'csv'){if(trajectory.value)window.open(`/api/results/${trajectory.value.runId}/export?format=${f}`,'_blank')}onMounted(()=>{refresh();loadSaved()});
</script>
<template><div class="app-shell"><header><div class="brand"><span class="mark">∿</span><span>SLAM / trajectory lab</span></div><span class="header-note">Локальная рабочая область</span></header><main><section class="intro"><div><p class="eyebrow">КАМЕРА · MP4</p><h1>Восстановите путь<br>из видеозаписи</h1><p class="lede">Загрузите ролик, запустите реконструкцию и сопоставьте движение камеры с каждым кадром.</p></div><div class="upload-box"><label class="upload-label"><input type="file" accept="video/mp4,video/*" @change="upload"><span class="upload-icon">＋</span><strong>{{video?'Заменить видео':'Выбрать MP4'}}</strong><small>{{video?.name||'До запуска файл остаётся на вашем компьютере'}}</small></label><video v-if="video&&!trajectory" :src="video.previewUrl" controls class="preview"></video><button class="primary" :disabled="!video||status.state==='running'" @click="start">{{status.state==='running'?'Обработка…':'Запустить восстановление'}}</button></div></section><div v-if="error" class="error">{{error}}</div><section v-if="status.state==='running'" class="run-status panel"><h2>{{status.stage||'Обрабатываем видео'}}</h2><div class="progress"><span :style="{width:(status.total?Math.round((status.processed||0)/status.total*100):0)+'%'}"></span></div><button class="secondary" @click="status.runId&&api.cancel(status.runId).then(s=>status=s)">Отменить</button></section><section v-if="trajectory" class="workspace"><div class="workspace-top"><h2>{{trajectory.video.name}}</h2><div class="actions"><button class="secondary" @click="exportData('json')">Экспорт JSON</button><button class="secondary" @click="exportData('csv')">Экспорт CSV</button></div></div><div class="viewer-grid"><div class="video-panel panel"><div class="video-frame"><video ref="media" :src="trajectory.video.previewUrl" controls @timeupdate="sync" @play="playing=true" @pause="playing=false"></video><span class="frame-label">{{time.toFixed(2)}} s</span></div><div class="transport"><button class="play" @click="toggle">{{playing?'Ⅱ':'▶'}}</button><input v-model.number="time" @input="seek" type="range" min="0" :max="video?.durationSec||1" step="0.01"><span class="num">{{time.toFixed(1)}} / {{video?.durationSec?.toFixed(1)}} s</span><select v-model.number="speed" @change="rate"><option :value="0.5">0.5×</option><option :value="1">1×</option><option :value="2">2×</option></select></div></div><div class="plot panel"><div class="plot-head"><h3>{{view==='map'?'Проекция X / Z':'Пространство X / Z'}}</h3><div class="segmented"><button :class="{active:view==='map'}" @click="view='map'">2D</button><button :class="{active:view==='space'}" @click="view='space'">3D</button></div></div><svg viewBox="0 0 560 300" role="img" aria-label="Проекция траектории"><path :d="path" class="axis"/><path :d="path" class="route" :stroke-dasharray="view==='space'?'6 8':'none'"/><circle v-if="active" :cx="active.x" :cy="active.y" r="7" class="current-dot"/></svg><div class="plot-foot">Оцененные позы · Разрыв {{model?.quality.maxGapSec?.toFixed(1)||'—'}} с</div></div></div><div class="detail-grid"><section class="panel metrics"><h3>Качество результата</h3><div class="metric-row"><div><span>Покрытие</span><b>{{Math.round((model?.quality.coverage||0)*100)}}%</b></div><div><span>Кадры</span><b>{{model?.quality.registeredFrames}} / {{model?.quality.sampledFrames}}</b></div><div><span>Точки 3D</span><b>{{model?.quality.points3D?.toLocaleString('ru-RU')}}</b></div><div><span>Репроекция</span><b>{{model?.quality.meanReprojectionErrorPx?.toFixed(2)||'—'}} px</b></div></div><p class="note">Масштаб координат произвольный. Ошибка не означает точность пути в метрах.</p></section><section class="panel settings"><h3>Модель и параметры</h3><label>Компонент<select v-model="modelId"><option v-for="m in trajectory.models" :key="m.id" :value="m.id">{{m.id}}</option></select></label><p>Движок <b>{{trajectory.engine}}</b></p><p>Позы <b>{{trajectory.poseConvention}}</b></p></section></div></section><section v-else class="empty-state panel"><h2>Результат появится здесь</h2><p>После обработки путь и качество синхронизируются с видео.</p></section><section class="saved"><h2>Сохранённые результаты</h2><button class="text-button" @click="loadSaved">Обновить</button><div v-for="item in saved" :key="item.runId" class="saved-row" @click="load(item.runId)"><b>{{item.videoName}}</b><span>{{item.registeredFrames}} / {{item.sampledFrames}} кадров</span></div></section></main></div></template>
